-- Rollback-safe schema/security/lifecycle validation. Never calls Gmail.
begin;
create temporary table __phase4c_test_init(id integer) on commit drop;
create or replace function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$begin if value is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
select pg_temp.assert_true(to_regclass('public.email_campaign_steps') is not null,'step table exists');
select pg_temp.assert_true(to_regclass('public.email_campaign_recipient_steps') is not null,'recipient step table exists');
select pg_temp.assert_true(to_regclass('public.email_campaign_signal_events') is not null,'signal table exists');
select pg_temp.assert_true(to_regprocedure('public.initialize_email_campaign_sequence(uuid,uuid)') is not null,'initialize RPC exists');
select pg_temp.assert_true(to_regprocedure('public.claim_email_campaign_sequence_steps(uuid,uuid,uuid,integer)') is not null,'claim RPC exists');
select pg_temp.assert_true(to_regprocedure('public.finalize_email_campaign_sequence_step(uuid,uuid,uuid,text,uuid,text)') is not null,'finalize RPC exists');
select pg_temp.assert_true(to_regprocedure('public.apply_email_campaign_signal(uuid,uuid,text,text,uuid,text)') is not null,'signal RPC exists');
select pg_temp.assert_true(not exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid='public.claim_email_campaign_sequence_steps(uuid,uuid,uuid,integer)'::regprocedure and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC claim denied');
select pg_temp.assert_true(not has_function_privilege('anon','public.claim_email_campaign_sequence_steps(uuid,uuid,uuid,integer)','EXECUTE'),'anon claim denied');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.claim_email_campaign_sequence_steps(uuid,uuid,uuid,integer)','EXECUTE'),'authenticated claim denied');
select pg_temp.assert_true(has_function_privilege('service_role','public.claim_email_campaign_sequence_steps(uuid,uuid,uuid,integer)','EXECUTE'),'service role claim allowed');
select pg_temp.assert_true((select relrowsecurity from pg_class where oid='public.email_campaign_steps'::regclass),'step RLS enabled');
select pg_temp.assert_true((select relrowsecurity from pg_class where oid='public.email_campaign_recipient_steps'::regclass),'delivery RLS enabled');
select pg_temp.assert_true((select relrowsecurity from pg_class where oid='public.email_campaign_signal_events'::regclass),'signal RLS enabled');
select pg_temp.assert_true((select count(*)=3 from pg_policies where schemaname='public' and tablename in ('email_campaign_steps','email_campaign_recipient_steps','email_campaign_signal_events')),'read policies present');
select pg_temp.assert_true((select count(distinct table_name)=3 from information_schema.column_privileges where grantee='authenticated' and table_schema='public' and table_name in ('email_campaign_steps','email_campaign_recipient_steps','email_campaign_signal_events') and privilege_type='SELECT'),'metadata columns readable');
select pg_temp.assert_true((select count(*)=0 from information_schema.table_privileges where grantee='authenticated' and table_schema='public' and table_name in ('email_campaign_steps','email_campaign_recipient_steps','email_campaign_signal_events') and privilege_type in('INSERT','UPDATE','DELETE')),'authenticated mutation denied');
select pg_temp.assert_true((select count(*)=0 from information_schema.routine_privileges where grantee='authenticated' and routine_schema='public' and routine_name in ('initialize_email_campaign_sequence','claim_email_campaign_sequence_steps','finalize_email_campaign_sequence_step','apply_email_campaign_signal')),'no authenticated mutation RPC');

-- Real lifecycle fixture. All identifiers are reserved for this rollback-only test.
create temporary table __phase4c_counts(kind text primary key,n integer not null default 0) on commit drop;
insert into __phase4c_counts values('lifecycle',0),('rejection',0);
create or replace function pg_temp.lifecycle(value boolean,label text) returns void language plpgsql as $$begin if value is not true then raise exception 'FAIL: %',label;end if;update __phase4c_counts set n=n+1 where kind='lifecycle';raise notice 'PASS: %',label;end$$;
create or replace function pg_temp.rejects(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then update __phase4c_counts set n=n+1 where kind='rejection';raise notice 'PASS expected rejection: %',label;return;end;raise exception 'FAIL expected rejection: %',label;end$$;
