select pg_temp.rejects($q$insert into public.email_campaign_steps(workspace_id,campaign_id,step_order,step_type,delay_minutes,subject_template,body_text_template) values('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000010',6,'FOLLOW_UP',1,'x','x')$q$,'sixth follow-up rejected');
