delete from public.email_campaign_steps where id='98000000-0000-4000-8000-000000000016';select pg_temp.lifecycle((select count(*)=5 from public.email_campaign_steps where campaign_id='98000000-0000-4000-8000-000000000010'),'DRAFT delete succeeds');
