select 'Structural/security assertions' label,18 value union all select 'Lifecycle success assertions',n from __phase4c_counts where kind='lifecycle' union all select 'Expected rejection assertions',n from __phase4c_counts where kind='rejection' union all select 'Total foundation checks',18+sum(n) from __phase4c_counts;
rollback;
